impl<'a> Ll1CallErrorParseTreeBuilder<'a> {
    pub fn new(tree_arena: &'a Bump) -> Self {
        Self { arena: tree_arena }
    }
}
impl<'a> ParseTreeBuilder<ParseTree<'a>> for Ll1CallErrorParseTreeBuilder<'a> {
    fn new_nonterminal_node(
        &self,
        nonterminal_node: &NonterminalNode,
        children: OneOrMany<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        match nonterminal_node.nonterminal_id {
            // S
            NonterminalId(0) => match nonterminal_node.return_slot {
                // S : Word Layout Word.
                SlotId(3) => {
                    let [word_0, layout, word_2] = children.into_array::<3usize>();
                    ParseTree::S(self.arena.alloc(S::Alt0 {
                        word_0: word_0.unwrap_token(),
                        layout: layout.unwrap_layout(),
                        word_2: word_2.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Layout
            NonterminalId(1) => match nonterminal_node.return_slot {
                // Layout : (WS | LineComment)* !>> WS !>> LineComment.
                SlotId(5) => {
                    let [star_0] = children.into_array::<1usize>();
                    ParseTree::Layout(self.arena.alloc(Layout::Alt0 {
                        star_0: star_0.unwrap_star_0(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Alt_0
            NonterminalId(2) => match nonterminal_node.return_slot {
                // (WS | LineComment) : WS.
                SlotId(7) => {
                    let [ws] = children.into_array::<1usize>();
                    ParseTree::Alt0(self.arena.alloc(Alt0::Alt0 {
                        ws: ws.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                // (WS | LineComment) : LineComment.
                SlotId(9) => {
                    let [line_comment] = children.into_array::<1usize>();
                    ParseTree::Alt0(self.arena.alloc(Alt0::Alt1 {
                        line_comment: line_comment.unwrap_token(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Plus_0
            NonterminalId(3) => match nonterminal_node.return_slot {
                // (WS | LineComment)+ : (WS | LineComment)+ (WS | LineComment).
                SlotId(12) => {
                    let [plus_0, alt_0] = children.into_array::<2usize>();
                    ParseTree::Plus0(self.arena.alloc(Plus0::Alt0 {
                        plus_0: plus_0.unwrap_plus_0(),
                        alt_0: alt_0.unwrap_alt_0(),
                        span: nonterminal_node.span,
                    }))
                }
                // (WS | LineComment)+ : (WS | LineComment).
                SlotId(14) => {
                    let [alt_0] = children.into_array::<1usize>();
                    ParseTree::Plus0(self.arena.alloc(Plus0::Alt1 {
                        alt_0: alt_0.unwrap_alt_0(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Opt_0
            NonterminalId(4) => match nonterminal_node.return_slot {
                // (WS | LineComment)+? : (WS | LineComment)+.
                SlotId(16) => {
                    let [plus_0] = children.into_array::<1usize>();
                    ParseTree::Opt0(self.arena.alloc(Opt0::Alt0 {
                        plus_0: plus_0.unwrap_plus_0(),
                        span: nonterminal_node.span,
                    }))
                }
                // (WS | LineComment)+? : .
                SlotId(17) => {
                    let [] = children.into_array::<0usize>();
                    ParseTree::Opt0(self.arena.alloc(Opt0::Alt1 {
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // Star_0
            NonterminalId(5) => match nonterminal_node.return_slot {
                // (WS | LineComment)* : (WS | LineComment)+?.
                SlotId(19) => {
                    let [opt_0] = children.into_array::<1usize>();
                    ParseTree::Star0(self.arena.alloc(Star0::Alt0 {
                        opt_0: opt_0.unwrap_opt_0(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            // StartS
            NonterminalId(6) => match nonterminal_node.return_slot {
                // S : Layout start:S Layout.
                SlotId(23) => {
                    let [layout_0, start, layout_2] = children.into_array::<3usize>();
                    ParseTree::StartS(self.arena.alloc(Start {
                        before: layout_0.unwrap_layout(),
                        node: start.unwrap_s(),
                        after: layout_2.unwrap_layout(),
                        span: nonterminal_node.span,
                    }))
                }
                _ => unreachable!(),
            },
            _ => unreachable!(),
        }
    }
    fn new_token(&self, terminal_node: &TerminalNode) -> ParseTree<'a> {
        ParseTree::Token(Token {
            kind: token_kind(terminal_node.terminal_id),
            span: terminal_node.span,
        })
    }
    fn new_ambiguity_node(
        &self,
        parent: NonterminalId,
        alternatives: Vec<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        match parent {
            crate::grammar_data::S => {
                let slice = self
                    .arena
                    .alloc_slice_fill_iter(alternatives.into_iter().map(|a| a.unwrap_s()));
                ParseTree::S(self.arena.alloc(S::Amb(slice)))
            }
            crate::grammar_data::LAYOUT => {
                let slice = self
                    .arena
                    .alloc_slice_fill_iter(alternatives.into_iter().map(|a| a.unwrap_layout()));
                ParseTree::Layout(self.arena.alloc(Layout::Amb(slice)))
            }
            crate::grammar_data::ALT_0 => {
                let slice = self
                    .arena
                    .alloc_slice_fill_iter(alternatives.into_iter().map(|a| a.unwrap_alt_0()));
                ParseTree::Alt0(self.arena.alloc(Alt0::Amb(slice)))
            }
            crate::grammar_data::PLUS_0 => {
                let slice = self
                    .arena
                    .alloc_slice_fill_iter(alternatives.into_iter().map(|a| a.unwrap_plus_0()));
                ParseTree::Plus0(self.arena.alloc(Plus0::Amb(slice)))
            }
            crate::grammar_data::OPT_0 => {
                let slice = self
                    .arena
                    .alloc_slice_fill_iter(alternatives.into_iter().map(|a| a.unwrap_opt_0()));
                ParseTree::Opt0(self.arena.alloc(Opt0::Amb(slice)))
            }
            crate::grammar_data::STAR_0 => {
                let slice = self
                    .arena
                    .alloc_slice_fill_iter(alternatives.into_iter().map(|a| a.unwrap_star_0()));
                ParseTree::Star0(self.arena.alloc(Star0::Amb(slice)))
            }
            crate::grammar_data::START_S => {
                let first = alternatives[0].unwrap_start_s();
                let inner = self.arena.alloc_slice_fill_iter(
                    alternatives.into_iter().map(|a| a.unwrap_start_s().node),
                );
                let node = &*self.arena.alloc(S::Amb(inner));
                ParseTree::StartS(self.arena.alloc(Start {
                    before: first.before,
                    node,
                    after: first.after,
                    span: first.span,
                }))
            }
            _ => unreachable!("nonterminal cannot be ambiguous"),
        }
    }
}
pub fn create_parse_tree<'a>(
    root_id: SPPFNodeId,
    nonterminal_id: NonterminalId,
    parser: &Ll1CallErrorParser,
    builder: &Ll1CallErrorParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    match nonterminal_id {
        crate::grammar_data::S => ParseTree::S(create_parse_tree_s(root_id, parser, builder)),
        crate::grammar_data::LAYOUT => {
            ParseTree::Layout(create_parse_tree_layout(root_id, parser, builder))
        }
        crate::grammar_data::ALT_0 => {
            ParseTree::Alt0(create_parse_tree_alt_0(root_id, parser, builder))
        }
        crate::grammar_data::PLUS_0 => {
            ParseTree::Plus0(create_parse_tree_plus_0(root_id, parser, builder))
        }
        crate::grammar_data::OPT_0 => {
            ParseTree::Opt0(create_parse_tree_opt_0(root_id, parser, builder))
        }
        crate::grammar_data::STAR_0 => {
            ParseTree::Star0(create_parse_tree_star_0(root_id, parser, builder))
        }
        crate::grammar_data::START_S => {
            ParseTree::StartS(create_parse_tree_start_s(root_id, parser, builder))
        }
        _ => panic!(),
    }
}
pub fn create_parse_tree_s<'a>(
    root_id: SPPFNodeId,
    parser: &Ll1CallErrorParser,
    builder: &Ll1CallErrorParseTreeBuilder<'a>,
) -> &'a S<'a> {
    visit_sppf(root_id, parser, builder).unwrap_one().unwrap_s()
}
